    content: `Ein Welpe ist aufgedreht, neugierig und scheint unerschöpflich — das verleitet viele Halter dazu, ihn möglichst viel laufen zu lassen. Ein verständlicher Impuls, aber ein potenziell schädlicher. Welpenknochen und Gelenke sind noch nicht ausgereift, und Überlastung in dieser Phase kann bleibende Schäden hinterlassen, die ein Leben lang Probleme machen.

## Die Wachstumsplatten: Der kritische Punkt

Junge Hunde haben offene **Wachstumsplatten** (Epiphysenfugen) — das ist Knorpelgewebe an den Knochenenden, das mit der Zeit zu echtem Knochen wird. Dieser Prozess ist erst abgeschlossen, wenn der Hund ausgewachsen ist. Bis dahin sind die Wachstumsplatten verletzungsanfällig.

**Wann ist der Wachstumsabschluss?**
- Kleine Rassen (unter 10 kg): ca. 8–10 Monate
- Mittlere Rassen (10–25 kg): ca. 12–14 Monate
- Große Rassen (25–45 kg): ca. 15–18 Monate
- Riesenwüchsige Rassen (über 45 kg): bis zu 24 Monate

## Was du bis zum Wachstumsabschluss vermeiden solltest

**Lange, kontinuierliche Strecken:** Lieber viele kurze Ausflüge als eine lange Runde. Der Welpe darf sich austoben — aber mit natürlichen Pausen, nicht im Dauerlauf.

**Weite Sprünge:** Aus dem Auto springen, über Hindernisse setzen, vom Sofa springen — all das erzeugt Stoßbelastungen auf noch nicht ausgereiften Gelenken.

**Treppen intensiv:** Gelegentliche Treppen im normalen Haushalt sind kein Drama, aber stundenlanges Treppensteigen oder steile Stiegen sollten vermieden werden.

**Rennen neben dem Fahrrad:** Erst nach abgeschlossenem Wachstum und schrittweisem Aufbau.

**Agility mit Sprüngen:** Erst wenn die Gelenke reif und der Grundgehorsam solide sind.

## Was Welpen brauchen

Statt intensiver Bewegung brauchen Welpen vor allem:
- Viel **freie Erkundung** in ihrem eigenen Tempo auf weichem Untergrund
- Kurze **Spieleinheiten** mit ausreichend Ruhephasen
- **Schnüffelarbeit** und einfache Such- und Lernspiele
- Sozialkontakt in sicherer, strukturierter Form

## Häufige Fragen

### Wie erkenne ich, ob mein Welpe überlastet ist?
Hinken, Schonen einer Pfote, Schlappheit oder das Verweigern weiterer Bewegung sind deutliche Zeichen. Aber: Ein Welpe stoppt nicht immer selbst — du musst die Grenzen setzen.

### Darf mein Welpe mit anderen Hunden toben?
Kurze Tobephasen mit verträglichen Spielkameraden sind wertvoll für die Sozialisation. Halte aber die Dauer im Blick und trenne rechtzeitig, bevor der Welpe überfordert ist.

### Wie viel Bewegung ist genau richtig?
Eine häufig genannte Faustregel: etwa 5 Minuten pro Lebensmonat, zweimal täglich. Das ist ein Orientierungswert — beobachte deinen Welpen und passe an.

## Das Wichtigste in Kürze

- Wachstumsplatten sind bis zum Wachstumsabschluss verletzungsanfällig
- Keine langen Strecken, weiten Sprünge oder intensives Treppensteigen
- Freie Erkundung, kurze Spieleinheiten und Schnüffelarbeit sind ideal
- Wachstumsabschluss je nach Rasse zwischen 8 und 24 Monaten`,
