    imageAlt: "Hund und Frauchen beim lockerem Aufwärm-Trab im Park",
    content: `Du würdest vor einem Lauf nicht sofort im Sprint starten — dein Hund sollte es auch nicht. Aufwärmen ist kein menschlicher Luxus, sondern eine physiologische Notwendigkeit. Muskeln, die kalt und unvorbereitet plötzlich auf Hochleistung schalten müssen, verletzen sich leichter. Wer vor dem Agility-Training, dem langen Wandern oder dem Schwimmen ein paar Minuten investiert, schützt seinen Hund wirksam.

## Was beim Aufwärmen passiert

Ein gezieltes Aufwärmprogramm erhöht schrittweise:
- **Durchblutung** in Muskeln und Sehnen
- **Körperkerntemperatur** — wärmere Muskeln sind elastischer
- **Gelenkflüssigkeit** — bessere Dämpfung und Beweglichkeit
- **Herzfrequenz** — sanfter Anstieg statt Schock-Belastung

Das Ergebnis: Muskeln, die weicher anspringen, Sehnen, die nicht reißen, Gelenke, die vorbereitet sind.

## Ein einfaches Aufwärmprogramm

**Phase 1 — Lockeres Gehen (3–5 Minuten):**
Starte mit normalem Schritttempo. Lass den Hund an der Leine locker mitlaufen, ohne Anforderungen an Leinenführigkeit oder Aufmerksamkeit zu stellen. Ziel: sanfte Aktivierung des Kreislaufs.

**Phase 2 — Leichter Trab (2–3 Minuten):**
Erhöhe das Tempo auf einen ruhigen Trab. Kein Sprint, kein Zurückhalten. Der Hund soll seinen natürlichen Bewegungsfluss finden.

**Phase 3 — Sanfte Übungen:**
- Langsames Sitzen und Aufstehen (2–3 Wiederholungen) — aktiviert Hüfte und Hinterbeine
- Rückwärtslaufen auf ebenem Untergrund (3–5 Schritte) — Tiefenmuskulatur
- Pfote auf eine Bank legen (beide Seiten) — Schulter und Vorderbeine strecken
- Slalom durch deine Beine (langsam) — Koordination und Körperwahrnehmung

## Wann Aufwärmen besonders wichtig ist

- Bei **intensivem Sport** (Agility, Zughundesport, Frisbee)
- Bei **kalter Witterung**, wenn die Muskeln kalt und steif sind
- Bei **älteren Hunden**, deren Gelenke mehr Zeit zum Anlaufen brauchen
- Bei **Hunden in der Reha**, nach Verletzungen oder Operationen
- Nach **längeren Ruhephasen** (morgens nach der Nacht, nach langer Autofahrt)

## Häufige Fragen

### Muss ich wirklich aufwärmen, wenn wir „nur" Gassi gehen?
Bei einem normalen Spaziergang ohne intensive Belastungsspitzen ist Aufwärmen kein Muss. Aber sobald Tempo, Sprünge oder sportliche Anforderungen kommen, lohnt sich die Investition.

### Wie erkenne ich, ob mein Hund „warm" ist?
Ein aufgewärmter Hund bewegt sich flüssiger, hebt die Beine freier und reagiert reaktionsschneller. Du wirst mit der Zeit ein Gefühl dafür entwickeln.

### Kann ich auch im Garten aufwärmen?
Ja — kurze Trab-Runden, sanfte Übungen und etwas Schnüffeln im Garten erfüllen denselben Zweck.

## Das Wichtigste in Kürze

- Aufwärmen erhöht Durchblutung, Körpertemperatur und Gelenkschmierung
- 5–10 Minuten lockeres Gehen, leichter Trab und sanfte Übungen reichen
- Besonders wichtig vor intensivem Sport, bei Kälte und bei älteren Hunden
- Ein aufgewärmter Hund verletzt sich seltener`,
