    title: "Agility: Wann dein Hund wirklich bereit ist",
    shortDescription:
      "Sprünge und Tunnel begeistern, brauchen aber sicheren Grundgehorsam und ausgewachsene Gelenke. So startest du agility-sicher und mit richtigem Aufbau.",
