    imageUrl: "/images/tipps/sport-bewegung/20.jpg",
    imageAlt: "Hund springt über eine Agility-Hürde auf einem Trainingsplatz",
    content: `Agility ist eine der begeisterndsten Hundesportarten — Hund und Mensch arbeiten als Team durch einen Hindernis-Parcours aus Hürden, Tunnel, Slalom-Stangen, Wippe und Laufsteg. Was auf Videos spektakulär aussieht, ist das Ergebnis von Monaten strukturiertem Training. Wer zu früh startet, gefährdet Gelenke und schafft schlechte Habits, die später schwer zu korrigieren sind.

## Die zwei Voraussetzungen für Agility-Start

### 1. Wachstumsabschluss
Agility-Hindernisse — besonders Sprünge — erzeugen erhebliche Stoßbelastungen auf Gelenke und Wachstumsplatten. Diese müssen vollständig geschlossen sein:
- Kleine Rassen: ab ca. 10–12 Monaten
- Mittlere Rassen: ab ca. 14–16 Monaten
- Große Rassen: ab ca. 18–24 Monaten

Vor dem Wachstumsabschluss: Nur **Tunnel, Slalom ohne Schwung und bodennahe Übungen** — keine Sprünge, keine Wippe, kein Laufsteg.

### 2. Sicherer Grundgehorsam
Agility auf einem gut gelenkten Parcours erfordert:
- Zuverlässiges Kommen auf Ruf
- Sitz, Platz und Warte auf Signal
- Grundlegende Leinenführigkeit
- Fokus auf den Handler — trotz Ablenkungen

Ohne diese Basis macht Agility keinen Sinn: Der Hund springt zwar über Hürden, aber nicht in der richtigen Reihenfolge, mit dem richtigen Timing oder unter Kontrolle.

## Wie Agility-Training aufgebaut wird

**Phase 1 — Einzel-Hindernisse:**
Jedes Hindernis wird einzeln eingeführt: Tunnel isoliert, dann Hürde allein (erst ganz niedrig), dann Wippe sehr langsam. Der Hund lernt, was jedes Gerät bedeutet, ohne Zeitdruck.

**Phase 2 — Mini-Parcours:**
2–3 Hindernisse werden verknüpft. Tempo ist Nebensache, Genauigkeit und Zusammenarbeit stehen im Vordergrund.

**Phase 3 — Längere Parcours:**
Erst wenn die Kommunikation stimmt, steigt die Komplexität. Tempo kommt von allein — drücke es nicht.

## Häufige Fragen

### In welchem Alter kann ein kleiner Hund mit Agility anfangen?
Kleine Rassen wachsen schneller — ab ca. 10–12 Monaten können die ersten Sprünge in voller Höhe trainiert werden. Vorher: nur bodennahe Übungen.

### Welche Rassen eignen sich besonders?
Border Collie, Australian Shepherd, Shetland Sheepdog und viele Terrier sind Klassiker. Aber auch Labradore, Mischlinge und überraschend viele andere Rassen lieben Agility.

### Muss ich in einem Verein trainieren?
Nicht zwingend, aber empfohlen. Ein erfahrener Trainer erkennt früh, wenn der Hund falsch läuft oder Hindernisse falsch nimmt — was langfristig Verletzungen verhindert.

## Das Wichtigste in Kürze

- Erst nach Wachstumsabschluss: Keine Sprünge auf jungen Gelenken
- Solider Grundgehorsam ist Voraussetzung, nicht optional
- Hindernisse einzeln einführen, Tempo kommt von selbst
- Verein oder erfahrener Trainer für den Einstieg empfohlen`,
