    id: 33,
    slug: "disc-dog-frisbee-sport",
    title: "Disc Dog: Wenn Hund und Mensch zur Frisbee-Artistik werden",
    shortDescription:
      "Disc Dog ist Frisbee als Hundesport — mit Sprüngen, Fangsequenzen und Choreografien. Was steckt hinter dem Sport und wie fängst du an?",
    level: 1,
    tags: ["disc dog", "frisbee", "sport", "koordination"],
    imageUrl: "/images/tipps/sport-bewegung/9.jpg",
    imageAlt: "Hund springt hoch in die Luft und fängt eine Frisbee-Scheibe",
    content: `Ein Hund, der drei Meter hoch springt und eine Frisbee-Scheibe aus der Luft greift — Disc Dog ist einer der spektakulärsten Hundesporte überhaupt. Aber hinter dem Flashigen steckt ein solides, systematisches Training, das für Hund und Mensch gleichermaßen fordernd und befriedigend ist.

## Was Disc Dog ist

Disc Dog ist der organisierte Sport rund um das Frisbee-Spielen mit Hund. Es gibt zwei Hauptdisziplinen:

**Toss & Fetch:** Hund und Handler wetteifern in kurzer Zeit um möglichst viele gefangene Scheiben. Je weiter die Scheibe fliegt und je näher am Handler gefangen, desto mehr Punkte.

**Freestyle:** Ein Choreografie-Programm mit Musik, das verschiedene Würfe, Sprünge, Tricks und Kombinationen zeigt. Hier liegt der Fokus auf Kreativität und Teamarbeit.

## Voraussetzungen

Disc Dog ist für jeden Hund geeignet, der:
- Freude am Apportieren und Fangen hat
- Körperlich gesund ist (Gelenke prüfen lassen, besonders bei Sprüngen)
- Mindestens 12–18 Monate alt ist (Wachstumsfugen müssen geschlossen sein)

Kurznasige Rassen (Bulldogge, Mops) sind für intensives Disc Dog ungeeignet — Hitzeprobleme und Atemwege machen schnelle Sprünge riskant.

## Wie du beginnst

**Schritt 1 — Scheibenliebe wecken:**
Nicht sofort werfen. Lass den Hund die Scheibe kennenlernen: rollen, schleifen, als Fressnapf nutzen, als Spielzeug zeigen. Die Scheibe soll begehrenswert werden.

**Schritt 2 — Kurze Würfe nahe am Körper:**
Erste Würfe gehen nur wenige Meter weit. Hund rennt, fängt (oder lernt es), bringt zurück. Immer belohnen.

**Schritt 3 — Abstand und Höhe steigern:**
Wenn Fangen sicher sitzt, kann Distanz und leichte Höhe dazukommen. Sprünge niemals erzwingen.

**Schritt 4 — Kurs besuchen:**
Ein Disc-Dog-Kurs oder ein Verein gibt Technik für Würfe und sicheres Sprungtraining.

## Häufige Fragen

### Welche Scheibe ist für Hunde geeignet?
Nur weiche Kunststoffscheiben verwenden, die speziell für Hunde produziert wurden. Harte Sportscheiben können Zähne beschädigen.

### Mein Hund springt nicht — ist er für Disc Dog ungeeignet?
Nicht unbedingt. Viele Hunde lernen das Springen erst, wenn sie den Dreh raus haben. Beginn mit rollenden Scheiben nahe am Boden.

### Wie oft darf ich Disc Dog üben?
2–3 Mal pro Woche, je 10–20 Minuten. Sprünge belasten Gelenke — ausreichend Erholung einplanen.

## Das Wichtigste in Kürze

- Disc Dog verbindet Sprint, Koordination und Teamarbeit
- Weiches Scheibenmaterial pflichtmäßig verwenden
- Sprünge erst nach vollständigem Knochenwachstum (ab 12–18 Monate)
- Mit Scheibenliebe und kurzen Bodenwürfen starten`,
