    imageAlt: "Läuferin mit Hund an Canicross-Zuggeschirr auf einem Waldpfad",
    content: `Canicross kommt aus dem Mushing — der Tradition der Schlittenhunde — und ist seit Jahren im Wachsen als urbaner und halburbaner Hundesport. Das Prinzip: Hund trägt ein Zuggeschirr, du trägst einen Hüftgurt, beide sind mit einem federnden Laufband verbunden. Der Hund zieht, du läufst — gemeinsam im Rhythmus durch Wald und Gelände.

## Was Canicross bietet

**Für den Hund:** Hochenergetische Auslastung mit klarer Aufgabe. Der Hund hat einen Job — ziehen — und erlebt das Laufen als Teamarbeit. Besonders gut geeignet für Rassen mit natürlichem Zugdrang (Husky, Malinois, Border Collie, Weimaraner).

**Für den Halter:** Intensives Lauftraining mit Motivation. Der Hund gibt das Tempo vor — und viele Läufer berichten, dass sie durch Canicross schneller und weiter laufen als allein.

**Als Team:** Die gemeinsame Bewegung stärkt die Bindung. Kommunikation per Körpersprache, Tempo und Richtungssignalen entsteht automatisch.

## Was du brauchst

- **Zuggeschirr für den Hund:** Speziell für Zugarbeit konstruiert — kein normales Brustgeschirr. Verteilt den Zug gleichmäßig auf Brust und Schultern, schont Hals und Rücken.
- **Hüftgurt für den Halter:** Mit Pufferleine (federndes Seil), damit Rucke abgefedert werden.
- **Lauferfahrung beim Hund:** Nie mit einem Welpen oder Junghund unter 18 Monaten starten — Gelenke müssen vollständig ausgewachsen sein.

## Wie du startest

1. Zuggeschirr eingewöhnen — tragen, ohne zu laufen
2. Kurze Einheiten auf ruhigem Gelände (Wald, Feldweg)
3. Kommandos einführen: Richtung (links/rechts), Tempo (schneller/langsamer), Stopp
4. Distanz schrittweise erhöhen

## Sicherheitsregeln

- Kein Canicross bei Temperaturen über 18–20°C — Hunde überhitzen beim Ziehen schnell
- Hund vor dem Sport kurz aufwärmen (langsames Gehen)
- Wasserpause alle 15–20 Minuten
- Bei Schmerzen oder Lahmheit sofort aufhören

## Häufige Fragen

### Welche Rassen sind für Canicross geeignet?
Hunde ab mittlerer Größe mit Energie und Zugmotivation. Kleine Hunde können Canicross machen, aber der Zug ist für kleine Körper intensiver.

### Muss mein Hund gut an der Leine gehen, bevor ich mit Canicross anfange?
Nein — Canicross erlaubt und fördert das Ziehen. Aber der Rückruf und Richtungskommandos müssen sitzen.

## Das Wichtigste in Kürze

- Canicross: Hund zieht, du läufst am Hüftgurt — intensive Teamarbeit
- Spezielles Zuggeschirr und Hüftgurt mit Pufferleine notwendig
- Erst ab 18 Monaten und nur bei kühlen Temperaturen
- Kommandos für Richtung und Tempo aufbauen`,
