    title: "Tauziehen mit Hund: Warum Zerrspiele gesund sind — mit klaren Regeln",
    shortDescription:
      "Tauziehen ist kein Dominanzspiel — es ist Bindungspflege. Mit den richtigen Regeln ist Zerren ein tolles gemeinsames Spiel ohne Risiken.",
