    imageUrl: "/images/tipps/sport-bewegung/2.jpg",
    imageAlt: "Hund fängt eine Frisbee-Scheibe in der Luft mit konzentriertem Blick",
    content: `Frisbee ist der unkompliziertere Einstieg in die Welt der Scheiben — kein Wettkampf, keine Choreos, einfach Scheibe werfen und fangen. Trotzdem verbirgt sich hinter einem gut funktionierenden Frisbee-Spiel mehr Technik als man denkt. Und mit der richtigen Einführung machen Hund und Halter gleichermaßen Fortschritte.

## Warum Frisbee so gut funktioniert

Eine Scheibe in der Luft triggert den Jagdinstinkt — Beute, die sich bewegt und fliegt, ist unwiderstehlich für viele Hunde. Das Fangen erfordert Timing, Koordination und Körperbewusstsein. Und der Wurf-Bring-Zyklus trainiert Apportieren in einer natürlichen, motivierenden Form.

## Was du brauchst

**Die richtige Scheibe:** Nur weiche Kunststoffscheiben verwenden — speziell für Hunde hergestellt (z.B. von Hyperflite oder Hero). Harte Wurfscheiben können Zähne und Zahnfleisch verletzen.

**Platz:** Ein freies Feld oder Wiese — mind. 20–30 Meter.

## Schritt-für-Schritt-Einführung

**Phase 1 — Scheibenliebe wecken:**
Scheibe auf dem Boden rollen, Leckerlis drauflegen, als Fressnapf benutzen. Der Hund soll die Scheibe als positives Objekt kennen.

**Phase 2 — Rollwürfe:**
Die Scheibe flach über den Boden rollen (nicht werfen). Hund verfolgt, schnappt, bringt. Große Belohnung.

**Phase 3 — Kurze Flugwürfe:**
Scheibe nur wenige Meter weit und flach werfen. Fangen auf niedrigem Niveau — kein Hochspringen nötig.

**Phase 4 — Distanz und Höhe steigern:**
Wenn Fangen sicher sitzt, Distanz erhöhen. Höhe erst steigern wenn Hund das Timing hat.

## Sicherheitsregeln

- Keine Sprünge von anderen Hunden oder Menschen als Absprungmöglichkeit nutzen
- Hitze: Frisbee in kühlen Stunden spielen
- Nicht übertreiben: 10–15 Fänge pro Session

## Häufige Fragen

### Was wenn mein Hund die Scheibe nicht apportiert?
Zwei Scheiben benutzen: Wenn Hund mit erster kommt, zweite zeigen — das motiviert zum Loslassen. Dann Scheibe 2 werfen.

### Kann ich auch mit einem kleinen Hund Frisbee spielen?
Ja — kleinere Scheiben für kleine Hunde. Rollwürfe statt Hochflüge.

### Ab welchem Alter?
Rollspiele ab 3–4 Monaten okay. Echte Sprünge erst ab 12–18 Monaten.

## Das Wichtigste in Kürze

- Nur weiche Hundescheiben verwenden — keine harten Wurfscheiben
- Mit Rollwürfen am Boden starten
- Scheibenliebe erst aufbauen, bevor geworfen wird
- 10–15 Fänge pro Session sind genug`,
