    id: 56,
    slug: "verletzungen-erkennen-hund",
    title: "Sportverletzungen beim Hund erkennen: Wann ist sofort zum Tierarzt?",
    shortDescription:
      "Hunde zeigen Schmerzen oft spät und subtil. Welche Zeichen auf eine Sportverletzung hinweisen und wann du nicht warten solltest.",
    level: 1,
    tags: ["verletzung", "sicherheit", "tierarzt", "sport"],
    imageUrl: "/images/tipps/sport-bewegung/8.jpg",
    imageAlt: "Hund hält eine Pfote hoch und schaut nachdenklich auf den Halter",
    content: `Hunde sind Meister darin, Schmerzen zu verbergen. Das ist evolutionär sinnvoll — ein schwaches Tier in der Wildnis macht sich zur Zielscheibe. Im Sport bedeutet das: Wenn ein Hund deutlich hinkt oder schmerzt, ist das Problem oft schon fortgeschrittener als es scheint.

## Die häufigsten Sportverletzungen

**Prellungen und Muskelzerrungen:** Entstehen durch Stürze, Kollisionen oder Überanstrengung. Symptome: Steifheit, Zögern bei bestimmten Bewegungen, leichtes Hinken.

**Pfotenverletzungen:** Risse, Schürfwunden, eingewachsene oder abgebrochene Krallen, Fremdkörper zwischen den Ballen. Symptome: Lecken der Pfote, Hinken, Aufsetzverweigerung.

**Kreuzbandriss:** Eine der häufigsten ernsthaften Sportverletzungen. Oft bei abrupten Stopps oder Sprüngen. Symptom: Plötzliches Hinken am Hinterbein, das nicht nachlässt.

**Muskelriss:** Selten, aber möglich bei extremen Sprints. Symptome: akuter Schmerz, sichtbare Schwellung.

**Wirbelprobleme (Bandscheibenvorfall):** Besonders bei chondrodystrophen Rassen. Symptome: Steife Wirbelsäule, Schmerzen bei Berührung des Rückens, Koordinationsprobleme.

## Wann sofort zum Tierarzt?

- **Akutes Hinken**, das nach 10 Minuten Pause nicht nachlässt
- **Nicht-Aufsetzen** einer Pfote oder eines Beins
- **Sichtbare Schwellung** oder Verformung
- **Koordinationsprobleme** (Wanken, Kreisen)
- **Schmerz bei Berührung** des Rückens
- **Bewusstlosigkeit** oder Orientierungslosigkeit
- **Starkes Bluten**

## Was du nie tun solltest

- Einen hinkenden Hund trotzdem weitertrainieren lassen
- Schmerzmittel für Menschen geben (Ibuprofen und Paracetamol sind für Hunde giftig)
- Abwarten, wenn Symptome länger als 24 Stunden anhalten

## Häufige Fragen

### Mein Hund hinkt direkt nach dem Sport, geht aber nach kurzer Pause wieder normal — Tierarzt nötig?
Wenn es sich regelmäßig wiederholt, ja. Einmalig nach sehr intensiver Einheit kann Muskelermüdung sein — beim nächsten Mal genauer beobachten.

### Wie erkenne ich Pfotenverletzungen?
Hund leckt auffällig an der Pfote, setzt sie nicht auf oder hält sie hoch. Pfote inspizieren: Ballen, zwischen den Zehen, Krallen.

## Das Wichtigste in Kürze

- Hunde zeigen Schmerzen oft spät — auf subtile Zeichen achten
- Pfoten nach Sport immer kurz kontrollieren
- Hinken, das nicht nachlässt: immer Tierarzt
- Niemals menschliche Schmerzmittel geben`,
