    id: 79,
    slug: "dummy-training-apportieren",
    title: "Dummy-Training für Apportierhunde",
    shortDescription:
      "Zielgerichtetes Training mit dem Dummy lastet Retriever und Co. tief aus und schult Impulskontrolle und Zusammenarbeit.",
    level: 2,
    tags: ["dummy", "apportieren"],
    imageUrl: "/images/tipps/sport-bewegung/7.jpg",
    imageAlt: "Labrador bringt einen Dummy zurück",
    content: `Das Apportieren ist für viele Rassen mehr als Spiel — es ist ein tief verwurzelter Trieb, der durch Jahrhunderte gezielter Züchtung entstanden ist. Retriever, Spaniel und Setter sind darauf ausgelegt, Wild zu suchen, zu finden und schonend zurückzubringen. Wer diesen Trieb mit strukturiertem Dummy-Training kanalisiert, gibt diesen Hunden genau das, was sie suchen — und erschöpft sie dabei auf die befriedigendste Weise.

## Was ist Dummy-Training?

Dummys sind Trainingsobjekte — meist zylindrische Stoffbeutel oder Gummikörper — die als Ersatz für echtes Wild beim Jagdhundtraining eingesetzt werden. Sie kommen in verschiedenen Gewichten (100 g bis 1 kg) und Materialien. Für strukturiertes Training zuhause sind Canvas-Dummys im 250-g-Format ein guter Einstieg.

## Was lernt der Hund beim Dummy-Training?

### Impulskontrolle
Der Hund lernt, den Dummy zu sehen, zu wollen — und trotzdem zu warten. Erst auf Signal wird apportiert. Kein anderes Spiel trainiert Impulskontrolle so direkten wie das Warten auf den Dummy-Wurf.

### Vertrauen in Signale
Der Hund orientiert sich an Sicht- und Handsignalen für Richtung und Entfernung — er lernt, seinen Blick auf den Menschen zu richten statt eigenständig zu handeln.

### Such- und Bringverhalten
Das Suchen nach einem versteckten oder gefallenen Dummy aktiviert Nasenarbeit und Problemlösefähigkeit.

## Aufbau des Trainings

**Phase 1 — Grundapport:** Dummy nahe werfen, Hund holen lassen. Kein Warten, kein Abgabeproblem lösen — erst Begeisterung wecken.

**Phase 2 — Impulskontrolle:** Warten einbauen. Hund sitzt, Dummy wird geworfen, Hund wartet auf Signal. Schrittweise die Wartezeit verlängern.

**Phase 3 — Richtungssignale:** Dummy verstecken, Hund von Position aus durch Handsignal in die richtige Richtung schicken.

**Phase 4 — Blindapport:** Dummy wird versteckt, ohne dass der Hund es sieht. Nun muss er auf Signale vertrauen.

## Für welche Rassen besonders geeignet?

Labrador, Golden Retriever, Flat-Coated Retriever, Cocker Spaniel, Weimaraner, Vizsla — grundsätzlich alle Retriever- und Vorstehhundrassen. Aber: Auch viele andere Hunde zeigen Apportierfreude und können davon profitieren.

## Das Wichtigste in Kürze

- Dummy-Training lastet Apportierhunde tief aus und schult Impulskontrolle
- Aufbau von Grundapport über Warten bis zu Richtungssignalen
- Canvas-Dummy 250 g als Einstieg empfohlen
- Ideal für Retriever und Vorstehhunde, aber nicht darauf beschränkt`,
