    title: "Kastrierte Hunde und Bewegung",
    shortDescription:
      "Gewichtsneigung nach Kastration durch mehr Bewegung ausgleichen. Was du nach der Kastration bei Fütterung und Aktivität beachten solltest.",
    level: 1,
    tags: ["kastration", "gewicht"],
    imageUrl: "/images/tipps/sport-bewegung/14.jpg",
    imageAlt: "Hund läuft aktiv auf einem Feldweg",
    content: `Die Kastration ist ein häufiger Eingriff bei Hunden — aus medizinischen Gründen, zur Verhaltensstabilisierung oder zur Verhinderung von Nachwuchs. Was viele Halter überrascht: Nach der Kastration verändert sich der Hormonstoffwechsel, und damit auch der Energiebedarf und die Neigung zur Gewichtszunahme. Wer das weiß, kann mit Fütterung und Bewegung gezielt gegensteuern.

## Warum kastrierte Hunde zur Gewichtszunahme neigen

Sexualhormone (Testosteron bei Rüden, Östrogen und Progesteron bei Hündinnen) haben unter anderem stoffwechselregulierende Funktionen. Nach der Kastration fehlen diese Hormone, was zu:
- **Reduziertem Grundumsatz** führt (der Körper verbraucht weniger im Ruhezustand)
- **Veränderten Sättigungssignalen** (manche kastrierten Hunde haben ein erhöhtes Hungergefühl)
- **Höherer Neigung zur Fetteinlagerung** beiträgt

Studien zeigen, dass kastrierte Hunde einen etwa 20–30 % niedrigeren Energiebedarf haben können als intakte Hunde gleicher Größe. Ohne Anpassung der Futtermenge ist Gewichtszunahme die Folge.

## Was Bewegung nach der Kastration bewirkt

Regelmäßige körperliche Aktivität:
- Erhöht den Kalorienverbrauch
- Erhält und stärkt Muskelmasse (was den Grundumsatz stabilisiert)
- Verbessert die Insulinsensitivität
- Unterstützt die psychische Balance

Bewegung allein kompensiert eine zu üppige Fütterung jedoch nicht vollständig — die Kombination aus angepasster Ration und mehr Aktivität ist entscheidend.

## Wann nach der OP wieder aktiv werden?

Nach dem Eingriff braucht der Hund Zeit zur Wundheilung:
- **Erste Woche:** Absolute Ruhephase, nur kurze Gassigänge
- **Woche 2–3:** Ruhige Spaziergänge, keine Sprünge oder Toben
- **Ab Woche 3–4:** Nach Rücksprache mit der Tierärztin kann die Aktivität langsam gesteigert werden

Den genauen Zeitplan besprich mit deiner Tierärztin — je nach Hund und Eingriff variiert die Heilungszeit.

## Langfristige Strategie

Bestehende Futterration nach der Kastration überprüfen und ggf. auf ein getreidereduziertes, eiweißreiches Futter umsteigen, das speziell für kastrierte Tiere ausgelegt ist. Dazu: tägliche, regelmäßige Bewegung als feste Routine etablieren.

## Das Wichtigste in Kürze

- Kastrierte Hunde haben ca. 20–30 % niedrigeren Energiebedarf
- Regelmäßige Bewegung hilft, Gewichtszunahme zu verhindern
- Erste Wochen nach der OP: Ruhephase einhalten
- Fütterung und Aktivität kombiniert für langfristiges Gewichtsmanagement`,
